-- 523: Original BrillaPrep NSMQ subj_nsmq_physics true_false_problem_of_day beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_523_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_523_guard;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_phys_kinematics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A ball is thrown vertically upwards with an initial speed of 20 m/s. Taking g = 10 m/s² and neglecting air resistance, calculate the maximum height reached and the total time of flight.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '20 m; total time 4 s' AND q.explanation IS 'At maximum height v = 0. Using v² = u² − 2gh: 0 = 20² − 2(10)h, so h = 400/20 = 20 m. Time to the peak: t = u/g = 20/10 = 2 s. By symmetry the descent takes another 2 s, giving a total time of flight of 4 s.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_pod_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_phys_thermodynamics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the heat energy absorbed when 0.2 kg of ice at 0 °C melts completely at the same temperature. (Specific latent heat of fusion of ice = 336 000 J/kg)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '67 200 J (67.2 kJ)' AND q.explanation IS 'During melting there is no temperature change, so the latent heat formula applies: Q = mL = 0.2 × 336 000 = 67 200 J = 67.2 kJ. The energy breaks the bonds of the solid lattice rather than raising the temperature.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_pod_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_tf_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_phys_mechanics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Total momentum is conserved in both elastic and inelastic collisions, provided no external force acts.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'Conservation of momentum follows from Newton’s third law and holds for every collision in an isolated system. What distinguishes elastic collisions is that kinetic energy is also conserved; in inelastic collisions some kinetic energy becomes heat or sound.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_tf_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_tf_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_phys_electricity' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The resistance of a metallic conductor increases as its temperature rises.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'In a metal, higher temperature makes the lattice ions vibrate more vigorously, so drifting electrons are scattered more often and resistance increases. This is why a filament lamp has a much higher resistance when hot than when cold.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_tf_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_tf_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_phys_waves' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Light waves require a material medium in order to propagate.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'False' AND q.explanation IS 'Light is an electromagnetic wave consisting of oscillating electric and magnetic fields, so it travels through a vacuum — which is how sunlight reaches the Earth. Only mechanical waves such as sound require a material medium.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_tf_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_523_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_tf_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_phys_thermodynamics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Temperature is a measure of the average kinetic energy of the particles in a substance.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'In kinetic theory, the absolute temperature of a substance is proportional to the mean translational kinetic energy of its particles. Heating a substance makes its particles move faster on average, which we register as a higher temperature.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_tf_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_pod_b002_001', 'topic_nsmq_phys_kinematics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'A ball is thrown vertically upwards with an initial speed of 20 m/s. Taking g = 10 m/s² and neglecting air resistance, calculate the maximum height reached and the total time of flight.', 'problem', 'problem_of_day', NULL, '20 m; total time 4 s', 'At maximum height v = 0. Using v² = u² − 2gh: 0 = 20² − 2(10)h, so h = 400/20 = 20 m. Time to the peak: t = u/g = 20/10 = 2 s. By symmetry the descent takes another 2 s, giving a total time of flight of 4 s.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
